class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def update(self, idx, val):
        self._update(1, 0, self.n - 1, idx, val)

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = max(self.tree[node], val)
            return
        mid = (start + end) // 2
        if start <= idx <= mid:
            self._update(2 * node, start, mid, idx, val)
        else:
            self._update(2 * node + 1, mid + 1, end, idx, val)
        self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, l, r):
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        p1 = self._query(2 * node, start, mid, l, r)
        p2 = self._query(2 * node + 1, mid + 1, end, l, r)
        return max(p1, p2)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    index = 1

    events = []
    for _ in range(n):
        mi = int(data[index])
        di = int(data[index + 1])
        li = int(data[index + 2])
        ri = int(data[index + 3])
        hi = int(data[index + 4])
        delta_di = int(data[index + 5])
        delta_xi = int(data[index + 6])
        delta_hi = int(data[index + 7])
        index += 8

        for k in range(mi):
            day = di + k * delta_di
            left = li + k * delta_xi
            right = ri + k * delta_xi
            height = hi + k * delta_hi
            events.append((day, left, right, height))

    events.sort()

    min_x = min(event[1] for event in events)
    max_x = max(event[2] for event in events)
    n_x = max_x - min_x + 1

    segment_tree = SegmentTree(n_x)

    missed_fogs = 0
    current_day = 0
    day_events = []

    for day, left, right, height in events:
        while current_day < day:
            current_day += 1
            if day_events:
                day_events.sort()
                for _, l, r, h in day_events:
                    segment_tree.update(l - min_x, h)
                day_events = []

        if segment_tree.query(left - min_x, right - min_x) < height:
            missed_fogs += 1
        day_events.append((day, left, right, height))

    print(missed_fogs)

